What does the following code print?

def f(a, key):
    low, high, c = 0, len(a) - 1, 0
    while low <= high:
        mid = (low + high) // 2
        c += 1
        if a[mid] == key:
            return c
        elif a[mid] < key:
            low = mid + 1
        else:
            high = mid - 1
    return c

a = [5, 9, 14, 20, 27, 33, 41, 48, 56, 63, 70, 82]
print(f(a, 63), f(a, 5), f(a, 100))
